fn prime_num(n: u64) -> bool {
    // Handle small cases
    if n < 2 {
        return false;
    }
    if n == 2 || n == 3 {
        return true;
    }
    // Even numbers greater than 2 are not prime
    if n % 2 == 0 {
        return false;
    }
    
    // Check odd divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    let mut divisor = 3;
    
    while divisor <= limit {
        if n % divisor == 0 {
            return false;
        }
        divisor += 2; // Skip even numbers
    }
    
    true
}